<?php
if(!defined('ABSPATH'))exit;
class WPST_Widget_Hero_Spotlight extends WPST_Elementor_Widget_Base{
 public function get_name(){return'wpsoft-hero-spotlight';} public function get_title(){return'WPSoft Hero · Spotlight';} public function get_icon(){return'eicon-lightbox';}
 protected function register_controls(){ $this->start_controls_section('content',array('label'=>'İçerik')); $this->add_control('eyebrow',array('label'=>'Etiket','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'CREATIVE DIGITAL STUDIO')); $this->add_control('title',array('label'=>'Başlık','type'=>\Elementor\Controls_Manager::TEXTAREA,'default'=>'Cesur fikirler.<br>Güçlü dijital deneyimler.')); $this->add_control('text',array('label'=>'Açıklama','type'=>\Elementor\Controls_Manager::TEXTAREA,'default'=>'Mouse spotlight etkili koyu ve premium hero tasarımı.')); $this->link_controls('button','Buton'); $this->wpst_signature_preset_control(); $this->add_control('layout',array('label'=>'Hero Kompozisyonu','type'=>\Elementor\Controls_Manager::SELECT,'default'=>'center','options'=>array('center'=>'Centered Spotlight','left'=>'Left Editorial','wide'=>'Wide Statement'),'prefix_class'=>'wpst-spotlight-layout-')); $this->add_control('spotlight_size',array('label'=>'Spotlight Boyutu','type'=>\Elementor\Controls_Manager::SLIDER,'range'=>array('px'=>array('min'=>180,'max'=>1000)),'default'=>array('size'=>560),'selectors'=>array('{{WRAPPER}} .wpst-ew-hero-spotlight'=>'--wpst-spotlight-size:{{SIZE}}px;'))); $this->add_control('spotlight_color',array('label'=>'Spotlight Rengi','type'=>\Elementor\Controls_Manager::COLOR,'selectors'=>array('{{WRAPPER}} .wpst-ew-hero-spotlight'=>'--wpst-spotlight-color:{{VALUE}};', '{{WRAPPER}} .wpst-spotlight'=>'background:radial-gradient(circle,{{VALUE}} 0%,transparent 68%)!important;'))); $this->add_control('show_orbit',array('label'=>'Orbit Efekti','type'=>\Elementor\Controls_Manager::SWITCHER,'return_value'=>'yes','default'=>'yes')); $this->end_controls_section(); $this->start_controls_section('hero_style',array('label'=>'Hero Biçimi','tab'=>\Elementor\Controls_Manager::TAB_STYLE)); $this->add_control('hero_bg',array('label'=>'Hero Arka Plan','type'=>\Elementor\Controls_Manager::COLOR,'selectors'=>array('{{WRAPPER}} .wpst-ew-hero-spotlight'=>'background:{{VALUE}}!important;'))); $this->add_responsive_control('hero_min_height',array('label'=>'Minimum Yükseklik','type'=>\Elementor\Controls_Manager::SLIDER,'size_units'=>array('px','vh'),'range'=>array('px'=>array('min'=>320,'max'=>1100),'vh'=>array('min'=>40,'max'=>100)),'selectors'=>array('{{WRAPPER}} .wpst-ew-hero-spotlight'=>'min-height:{{SIZE}}{{UNIT}};'))); $this->add_responsive_control('content_width',array('label'=>'İçerik Maks. Genişlik','type'=>\Elementor\Controls_Manager::SLIDER,'range'=>array('px'=>array('min'=>320,'max'=>1200)),'selectors'=>array('{{WRAPPER}} .wpst-hsp-inner'=>'max-width:{{SIZE}}px;'))); $this->end_controls_section(); $this->hero_button_style_controls();
        $this->standard_responsive_controls(); }
 protected function render(){ $s=$this->get_settings_for_display(); echo'<section class="wpst-ew-hero-spotlight"><div class="wpst-spotlight"></div><div class="wpst-hsp-inner"><small>'.esc_html($s['eyebrow']).'</small><h1>'.wp_kses_post($s['title']).'</h1><p>'.esc_html($s['text']).'</p>'; if($s['button_text'])echo'<a'.$this->render_link_attrs($s['button_url']).'>'.esc_html($s['button_text']).' <span class="wpst-cta-arrow is-diagonal" aria-hidden="true"></span></a>'; echo'</div>'; if('yes'===$s['show_orbit'])echo'<span class="wpst-hsp-orbit"></span>'; echo'</section>'; }
}